import CoreGraphics
import Foundation
import Testing
@testable import MouseGestureCore

/// Fixtures recorded on 2026-10-17 with a listen-only event tap while the
/// Deskflow mouse made right-button swipes and plain right-clicks. Each move is
/// "milliseconds relative to the press@x,y".
struct PrePressGestureTests {
    struct Sample {
        let pre: String, press: String, drags: String, release: String
        let expected: GestureDirection?

        static func point(_ text: Substring) -> CGPoint {
            let parts = text.split(separator: ",").map { CGFloat(Double($0)!) }
            return CGPoint(x: parts[0], y: parts[1])
        }

        /// Recorded strokes are replayed clicks: press and release arrive together.
        func direction(threshold: CGFloat = 8, releaseDelay: TimeInterval = 0) -> GestureDirection? {
            let pressedAt: TimeInterval = 100
            let samples = pre.split(separator: " ").map { item -> MotionSample in
                let parts = item.split(separator: "@")
                return MotionSample(time: pressedAt + Double(parts[0])! / 1_000, point: Self.point(parts[1]))
            }
            return PrePressGesture.direction(
                before: samples, pressedAt: pressedAt, press: Self.point(Substring(press)),
                drags: drags.split(separator: " ").map { Self.point($0) }, release: Self.point(Substring(release)),
                releasedAt: pressedAt + releaseDelay, threshold: threshold)
        }
    }

