    @Test(arguments: deskflowSamples)
    func recordedDeskflowStroke(_ sample: Sample) {
        #expect(sample.direction() == sample.expected)
    }

    @Test func shortSwipeRecoversDistanceFromMovesBeforeThePress() {
        // Only 4 pt arrive between press and release; the stroke itself came first.
        let sample = Sample(pre: "-60@500,470 -52@500,474 -44@500,479 -36@500,484 -28@500,490",
                            press: "500,490", drags: "500,492 500,494", release: "500,494", expected: .down)
        #expect(sample.direction() == .down)
        #expect(sample.direction(threshold: 40) == nil)
        // A real press held 100 ms is judged by its own drags only.
        #expect(sample.direction(releaseDelay: 0.1) == nil)
    }

    @Test func pausedCursorBeforeClickIsNotUsed() {
        let sample = Sample(pre: "-180@500,400 -172@500,420 -164@500,440",
                            press: "500,440", drags: "500,443", release: "500,444", expected: nil)
        #expect(sample.direction() == nil)
    }

    @Test func positioningInAnotherDirectionStopsTheLookback() {
        // Horizontal travel to the target, then a short downward stroke.
        let sample = Sample(pre: "-40@400,500 -32@440,500 -24@480,500 -16@500,500",
                            press: "500,500", drags: "500,504", release: "500,505", expected: nil)
        #expect(sample.direction() == nil)
    }

    @Test func clickWithoutDragsNeedsMotionUpToTheClick() {
        // Short Deskflow strokes arrive as a click with the motion just before it.
        let moving = Sample(pre: "-40@500,540 -32@500,530 -24@500,520 -16@500,510 -8@500,505",
                            press: "500,500", drags: "", release: "500,500", expected: .up)
        #expect(moving.direction() == .up)
        // An ordinary click comes after the cursor rested for the whole press.
        let rested = Sample(pre: "-160@500,540 -152@500,530 -144@500,520 -136@500,510 -128@500,500",
                            press: "500,500", drags: "", release: "500,500", expected: nil)
        #expect(rested.direction() == nil)
        // Sideways travel straight into a click never becomes a gesture.
        let sideways = Sample(pre: "-24@440,500 -16@460,500 -8@480,500",
                              press: "500,500", drags: "", release: "500,500", expected: nil)
        #expect(sideways.direction() == nil)
        // A real click held for 90 ms after the same motion stays a click.
        #expect(moving.direction(releaseDelay: 0.09) == nil)
    }

    @Test func recentMotionKeepsOnlyTheLookbackWindow() {
        var motion = RecentMotion()
        motion.record(.zero, at: 1)
        motion.record(CGPoint(x: 1, y: 1), at: 1.5)
        motion.record(CGPoint(x: 2, y: 2), at: 1.7)
        #expect(motion.samples.map(\.time) == [1.5, 1.7])
    }
}

extension PrePressGestureTests.Sample: CustomTestStringConvertible {
    var testDescription: String { "press \(press) expected \(expected?.rawValue ?? "none")" }
}
